function ls(k,v){try{if(v===undefined){const x=localStorage.getItem('arbor.'+k);return x?JSON.parse(x):null}localStorage.setItem('arbor.'+k,JSON.stringify(v))}catch(e){return null}}
function toast(msg,action){const t=document.createElement('div');t.className='toast';t.innerHTML=`<span>${esc(msg)}</span>${action?`<button type="button">${esc(action.t)}</button>`:''}`;$('#toasts').appendChild(t);if(action)$('button',t).onclick=()=>{t.remove();action.run()};setTimeout(()=>{t.style.transition='opacity .3s';t.style.opacity=0;setTimeout(()=>t.remove(),300)},3200)}
