const S={cart:ls('cart')||[],wish:new Set(ls('wish')||[]),cur:'USD',disc:null,cat:'All',shop:{cats:new Set(),max:1500,colors:new Set(),sale:false,sort:'featured'},user:ls('user'),orders:[],appts:[],reviews:{},newsCode:null,co:{step:1,info:{},ship:'standard'}};
const CUR={USD:['$',1],AUD:['A$',1.52],EUR:['€',.92]};
const money=(usd,d=0)=>{const [s,r]=CUR[S.cur];const v=usd*r;return s+fmtN(d?v:Math.round(v),d)};
const DISC={WELCOME30:{pct:30,label:'30% off your first order'},ARBOR10:{pct:10,label:'10% off'}};
const FREE=500;
function saveCart(){ls('cart',S.cart);ls('wish',[...S.wish]);updateBadges()}
const cartCount=()=>S.cart.reduce((a,l)=>a+l.q,0);
const subtotal=()=>S.cart.reduce((a,l)=>a+byslug(l.s).price*l.q,0);
function totals(ship='standard'){const sub=subtotal();const dsc=S.disc?Math.round(sub*DISC[S.disc].pct)/100:0;const after=sub-dsc;let sh=after>=FREE||!sub?0:49;if(ship==='white')sh+=79;if(ship==='express')sh+=129;const tax=Math.round((after+sh)*0.0825*100)/100;return {sub,dsc,sh,tax,total:after+sh+tax}}
function addToCart(slug,vi=0,q=1,silent){const l=S.cart.find(x=>x.s===slug&&x.v===vi);if(l)l.q+=q;else S.cart.push({s:slug,v:vi,q});saveCart();const b=$('#cartN');if(b){b.classList.remove('pop');void b.offsetWidth;b.classList.add('pop')}
 if(!silent)toast(`${byslug(slug).name} added to cart`,{t:'View cart',run:openCart})}
function updateBadges(){const n=cartCount();const b=$('#cartN');if(b){b.textContent=n;b.hidden=!n}const w=$('#wishN');if(w){w.textContent=S.wish.size;w.hidden=!S.wish.size}}
function toggleWish(slug,btn){if(S.wish.has(slug)){S.wish.delete(slug);toast('Removed from wishlist')}else{S.wish.add(slug);toast('Saved to wishlist',{t:'View',run:()=>location.hash='wishlist'})}saveCart();$$(`[data-wish="${slug}"]`).forEach(b=>b.setAttribute('aria-pressed',S.wish.has(slug)))}

