 $('#newsF').onsubmit=e=>{e.preventDefault();const v=$('#newsE').value.trim();const ok=/^\S+@\S+\.\S+$/.test(v);$('#newsE').classList.toggle('err',!ok);$('#newsErr').hidden=ok;if(!ok)return;S.newsCode='WELCOME30';
  $('#newsCode').innerHTML=`<p style="margin-top:18px">You're in. Your code for 30% off:</p><div class="code-box"><span>WELCOME30</span><button class="btn dark sm" type="button" id="applyCode">Apply to cart</button><button class="iconbtn" type="button" id="copyCode" aria-label="Copy code">${ic('copy')}</button></div>`;$('#newsE').value='';
  $('#applyCode').onclick=()=>{S.disc='WELCOME30';toast('WELCOME30 applied: 30% off',{t:'View cart',run:openCart})};$('#copyCode').onclick=()=>{try{navigator.clipboard.writeText('WELCOME30').then(()=>toast('Code copied'),()=>toast('Code: WELCOME30'))}catch(_){toast('Code: WELCOME30')}}};
