function pageShop(){const colors=[['Blue','#8FA9C4'],['Green','#9DBAA5'],['Neutral','#D9CBB4'],['Pink','#E3B8AE'],['Grey','#6B6E73']];
 return `<div class="wrap page-h"><div class="crumbs"><a href="#home">Home</a>/<span>Products</span></div><h1>All furniture</h1></div>
 <div class="wrap shop"><aside class="filters" aria-label="Filters"><div><h4>Category</h4>${CATS.slice(1).map(c=>`<label class="ck"><input type="checkbox" data-fc="${c}" ${S.shop.cats.has(c)?'checked':''}> ${c} <span class="muted num" style="margin-left:auto">${P.filter(p=>p.cat===c).length}</span></label>`).join('')}</div>
  <div><h4>Max price · <span class="num" id="maxV">${money(S.shop.max)}</span></h4><input type="range" id="maxR" min="100" max="1500" step="50" value="${S.shop.max}" aria-label="Maximum price"></div>
  <div><h4>Colour</h4><div class="sws">${colors.map(c=>`<button type="button" class="dot-sw" data-col="${c[0]}" aria-pressed="${S.shop.colors.has(c[0])}" title="${c[0]}" aria-label="${c[0]}" style="background:${c[1]}"></button>`).join('')}</div></div>
  <div><label class="ck"><input type="checkbox" id="saleOnly" ${S.shop.sale?'checked':''}> On sale only</label></div><button class="link" id="clrF" type="button">Clear all filters</button></aside>
  <div><div class="shop-top"><span class="muted" id="cnt"></span><label class="sr" for="sort">Sort</label><select class="sel" id="sort">${[['featured','Featured'],['low','Price: low to high'],['high','Price: high to low'],['rating','Top rated'],['az','Name A–Z']].map(o=>`<option value="${o[0]}" ${o[0]===S.shop.sort?'selected':''}>${o[1]}</option>`).join('')}</select></div><div class="grid" id="shopGrid"></div></div></div>`}
const colorGroup=hex=>{const n=parseInt(hex.slice(1),16),r=n>>16,g=(n>>8)&255,b=n&255;if(r<130&&g<130&&b<130)return 'Grey';if(b>r+10&&b>=g)return 'Blue';if(g>r&&g>b)return 'Green';if(r>g+18&&r>b+18)return 'Pink';return 'Neutral'};
function bindShop(){const draw=()=>{const f=S.shop;let l=P.filter(p=>(!f.cats.size||f.cats.has(p.cat))&&p.price<=f.max&&(!f.sale||p.compare)&&(!f.colors.size||p.v.some(v=>f.colors.has(colorGroup(v[1])))));
  const so={low:(a,b)=>a.price-b.price,high:(a,b)=>b.price-a.price,rating:(a,b)=>b.rating-a.rating,az:(a,b)=>a.name.localeCompare(b.name)}[f.sort];if(so)l=[...l].sort(so);
  $('#cnt').textContent=`${l.length} of ${P.length} pieces`;$('#shopGrid').innerHTML=l.length?l.map(card).join(''):`<div class="empty" style="grid-column:1/-1">Nothing matches these filters. <button class="btn sm" id="clr2" style="margin-left:8px">Clear filters</button></div>`;bindCards($('#shopGrid'));$('#clr2')?.addEventListener('click',clear)};
 const clear=()=>{S.shop={cats:new Set(),max:1500,colors:new Set(),sale:false,sort:S.shop.sort};route()};
 $$('[data-fc]').forEach(c=>c.onchange=()=>{c.checked?S.shop.cats.add(c.dataset.fc):S.shop.cats.delete(c.dataset.fc);draw()});
 $('#maxR').oninput=e=>{S.shop.max=+e.target.value;$('#maxV').textContent=money(S.shop.max);draw()};
 $$('[data-col]').forEach(b=>b.onclick=()=>{const c=b.dataset.col;S.shop.colors.has(c)?S.shop.colors.delete(c):S.shop.colors.add(c);b.setAttribute('aria-pressed',S.shop.colors.has(c));draw()});
 $('#saleOnly').onchange=e=>{S.shop.sale=e.target.checked;draw()};$('#sort').onchange=e=>{S.shop.sort=e.target.value;draw()};$('#clrF').onclick=clear;draw()}

