 $('#qm').onclick=()=>{$('#qv').value=Math.max(1,q()-1);upd()};$('#qp').onclick=()=>{$('#qv').value=Math.min(20,q()+1);upd()};$('#qv').oninput=upd;$('#qv').onblur=()=>{$('#qv').value=q();upd()};
 $('#addBtn').onclick=()=>{addToCart(p.slug,vi,q());const b=$('#addBtn');b.innerHTML=ic('check')+' Added to cart';setTimeout(()=>{if(!document.body.contains(b)||!$('#qv'))return;b.innerHTML=`Add to cart · <span class="num" id="addPrice">${money(p.price*q())}</span>`},1500)};
